"""
sliding_window_limiter.py

A sliding-window rate limiter keyed by arbitrary string keys.
"""

from collections import deque


class SlidingWindowLimiter:
    """Rate limiter using a half-open sliding window (timestamp - window_seconds, timestamp]."""

    def __init__(self, limit: int, window_seconds: int) -> None:
        if not isinstance(limit, int):
            raise TypeError(f"limit must be an int, got {type(limit).__name__!r}")
        if not isinstance(window_seconds, int):
            raise TypeError(f"window_seconds must be an int, got {type(window_seconds).__name__!r}")
        if limit <= 0:
            raise ValueError(f"limit must be positive, got {limit!r}")
        if window_seconds <= 0:
            raise ValueError(f"window_seconds must be positive, got {window_seconds!r}")

        self._limit = limit
        self._window = window_seconds
        # key -> deque of accepted timestamps in ascending order
        self._store: dict[str, deque[int]] = {}

    # ------------------------------------------------------------------
    # Internal helpers
    # ------------------------------------------------------------------

    def _evict_expired(self, timestamps: deque[int], current: int) -> None:
        """Remove timestamps that fall outside (current - window_seconds, current]."""
        cutoff = current - self._window
        while timestamps and timestamps[0] <= cutoff:
            timestamps.popleft()

    def _timestamps_for(self, key: str) -> deque[int]:
        if key not in self._store:
            self._store[key] = deque()
        return self._store[key]

    def _pruned_timestamps(self, key: str, timestamp: int) -> deque[int]:
        """Return the deque for *key* after evicting expired entries."""
        timestamps = self._timestamps_for(key)
        self._evict_expired(timestamps, timestamp)
        return timestamps

    @staticmethod
    def _validate_key(key: object) -> None:
        if not isinstance(key, str):
            raise TypeError(f"key must be a str, got {type(key).__name__!r}")

    @staticmethod
    def _validate_timestamp(timestamp: object) -> None:
        if not isinstance(timestamp, int):
            raise TypeError(f"timestamp must be an int, got {type(timestamp).__name__!r}")

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------

    def allow(self, key: str, timestamp: int) -> bool:
        """
        Return True and record the event if the key has fewer than *limit*
        events in (timestamp - window_seconds, timestamp].
        Return False without recording otherwise.
        """
        self._validate_key(key)
        self._validate_timestamp(timestamp)

        timestamps = self._pruned_timestamps(key, timestamp)

        if len(timestamps) < self._limit:
            timestamps.append(timestamp)
            return True

        return False

    def remaining(self, key: str, timestamp: int) -> int:
        """
        Prune expired events the same way as allow(), without recording a new
        event, and return how many events can still be accepted for *key* at
        *timestamp*.
        """
        self._validate_key(key)
        self._validate_timestamp(timestamp)

        timestamps = self._pruned_timestamps(key, timestamp)
        return max(0, self._limit - len(timestamps))

    def snapshot(self, key: str) -> list[int]:
        """Return the currently retained timestamps for *key* as a sorted list."""
        self._validate_key(key)

        if key not in self._store:
            return []
        return list(self._store[key])

